+class Sphere {
+public:
+  static Scalar f(const Eigen::Matrix<Scalar, N, 1>& x) { return x.array().square().sum(); }
+
+  static Eigen::Matrix<Scalar, 1, N> j(const Eigen::Matrix<Scalar, N, 1>& x) { return 2 * x; }
