+template<typename PointSource, typename PointTarget>
+void FastVGICPCuda<PointSource, PointTarget>::setInputSource(const PointCloudSourceConstPtr& cloud) {
+  // the input cloud is the same as the previous one
+  if(cloud == input_) {
